def with_plus(n)
  s = ""
  ids = []
  n.times { s += "x"; ids << s.object_id }
  ids.uniq.size
end

def with_append(n)
  s = ""
  ids = []
  n.times { s << "x"; ids << s.object_id }
  ids.uniq.size
end

p [with_plus(5), with_append(5)]
